[
  {
    "statement": "There is insufficient evidence to determine which approach, habitat restoration or artificial habitat creation, is more effective for seal conservation.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effects of creating artificial habitat for marine and freshwater mammals.",
    "citations": [
      "2921"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on marine and freshwater mammal populations of leaving anthropogenic structures in place after decommissioning.",
    "citations": [
      "2922"
    ]
  },
  {
    "statement": "Translocating Hawaiian monk seals resulted in 50-83% survival rates for at least one year.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "More than a quarter of translocated Hawaiian monk seals reproduced.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "The survival rates for translocated Hawaiian monk seals were similar to or greater than the survival rates for non-translocated pups.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "The translocation of Hawaiian monk seals involved moving animals rather than habitat creation or restoration.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "Restored or created coastal and intertidal wetlands were used by target bird species.",
    "citations": [
      "367"
    ]
  },
  {
    "statement": "In some cases, the numbers and/or diversity of bird species in restored or created wetlands were at least as high as in natural wetlands.",
    "citations": [
      "367"
    ]
  },
  {
    "statement": "Artificial reefs can support marine invertebrate communities.",
    "citations": [
      "2258"
    ]
  },
  {
    "statement": "The community composition of marine invertebrates on artificial reefs differed from that on natural reefs.",
    "citations": [
      "2258"
    ]
  },
  {
    "statement": "Species richness on artificial reefs was often lower than on natural reefs.",
    "citations": [
      "2258"
    ]
  },
  {
    "statement": "Habitat restoration intended to offset lost habitat was colonized by over 198 invertebrate species.",
    "citations": [
      "2265"
    ]
  },
  {
    "statement": "The evidence base specifically addressing seal habitat restoration versus artificial habitat creation is currently lacking.",
    "citations": []
  }
]
